import type * as React from "react";
import type { RenderFn } from "./render-fn.js";

export type { RenderCallbackProps, RenderFn } from "./render-fn.js";

/**
 * The element props plus the render override, the way a headless primitive
 * library mixes its render prop into every component's props. The second
 * intersection member is an anonymous type literal declared here, in the
 * dependency, so a consumer's props type never spells its shape out.
 */
export type ComponentProps<ElementType extends React.ElementType> = React.ComponentPropsWithRef<ElementType> & {
  /**
   * Replaces the rendered element.
   */
  render?: React.ReactElement | RenderFn | undefined;
};

/** A host object a consumer's props may reference by class. */
export declare class RenderHost {
  readonly id: string;
}
